import os,json,pathlib,base64,hashlib,urllib.request,subprocess,shutil
root=pathlib.Path('/home/appontrack/public_html/ayo')
expected=json.loads(__import__('sys').argv[1])
backup=pathlib.Path('/home/appontrack/.ayo-inline-chat-v11-backup-20261105')
if set(expected)!={'app.js','index.php'} or backup.exists():raise RuntimeError('unsafe deployment')
token=json.loads(pathlib.Path('/home/appontrack/ontrack-voice-link/config.json').read_text())['token']
heads={'Authorization':'Bearer '+token,'Accept':'application/vnd.github+json','User-Agent':'OnTrack-AYO-Publisher'}
blobs={}
for name,sha in expected.items():
 url='https://api.github.com/repos/OnTrack-Development/OnTrack-voice/contents/ayo/'+name+'?ref=feat/ayo-php-host-demo-20261105'
 with urllib.request.urlopen(urllib.request.Request(url,headers=heads),timeout=8) as r:d=json.load(r)
 raw=base64.b64decode(d['content'])
 h=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()
 if d.get('sha')!=sha or h!=sha:raise RuntimeError('source SHA mismatch '+name)
 blobs[name]=raw
php=shutil.which('php') or '/usr/local/bin/php'
with __import__('tempfile').TemporaryDirectory(dir='/home/appontrack') as d:
 p=pathlib.Path(d)/'index.php';p.write_bytes(blobs['index.php'])
 r=subprocess.run([php,'-l',str(p)],capture_output=True,text=True,timeout=6)
 if r.returncode:raise RuntimeError('PHP lint failure')
backup.mkdir(mode=0o700)
for name in expected:
 p=root/name
 if not p.is_file() or p.is_symlink():raise RuntimeError('missing/symlink '+name)
 (backup/name).write_bytes(p.read_bytes())
changed=[]
try:
 for name,raw in blobs.items():
  target=root/name;temp=root/(name+'.v11tmp')
  fd=os.open(temp,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o644)
  with os.fdopen(fd,'wb') as f:f.write(raw)
  os.chmod(temp,0o644);os.replace(temp,target);changed.append(name)
except:
 for name in changed:
  (root/name).write_bytes((backup/name).read_bytes());os.chmod(root/name,0o644)
 raise
print(json.dumps({'status':'deployed','version':'v11','files':changed,'integrity':'ok','php_lint':'ok'}))
